result:
.btn-text{
  cursor:pointer;
  display: inline-block;
  margin: 0 10px;
  color: #0d8eff;
}
.datePicker{
  overflow: hidden;
  margin-right: 4px;
  vertical-align: middle;
}
.fliter-item{
  display: inline-block;
  overflow: hidden;
  margin-right: 4px;
  vertical-align: middle;
}
.container-box .el-dialog__wrapper .input {
  width: 224px;
}
@keyframes warn {
  0% {
    transform: scale(0.5);
    opacity: 1;
  }

  30% {
    opacity: 1;
  }

  100% {
    transform: scale(1.4);
    opacity: 0;
  }
}
.timeout-point {
  width: 6px;
  height: 6px;
  background-color: #FD3A3A;
  position: absolute;
  top: 0;
  left: 0;
  border-radius: 50%;
}
.point-flicker:after {
  background-color: #FD3A3A;
}
.point-flicker:before {
  background-color: rgba(255, 209, 208, 1);
}
.point-flicker:before,
.point-flicker:after {
  content: '';
  width: 8px;
  height: 8px;
  position: absolute;
  left: 50%;
  top: 50%;
  margin-left: -4px;
  margin-top: -4px;
  border-radius: 50%;
  animation: warn 1.5s ease-out 0s infinite;
}
.timeout{
  color: #FD3A3A;
}
.timeout ::v-deep span{
  position: relative;
  top: 4px;
  left: -13px;
}
.no-timeout{
  color: #2794F8;
}
.no-timeout ::v-deep span{
  position: relative;
  top: 13px;
  left: 6px;
}
.no-timeout-point{
  width: 6px;
  height: 6px;
  border-radius: 50px;
  background: #2794F8;
  position: absolute;
}
.filter-tree{
  overflow: auto;
  height: 270px;
}
